pub struct FakeUserRepo {
    pub rows: std::cell::RefCell<Vec<(u64, String)>>,
}

impl super::UserRepo for FakeUserRepo {
    fn find(&self, id: u64) -> Option<User> {
        self.rows.borrow().iter()
            .find(|(rid, _)| *rid == id)
            .map(|(id, name)| User { id: *id, name: name.clone() })
    }
}
